package vn.svframe.svframelib.api.crafting.uifilters;
import vn.svframe.svframelib.api.item.NBTItem; import vn.svframe.svframelib.api.util.ui.FriendlyFeedbackProvider; import net.minecraft.item.ItemStack;
public class SVFrameItemUIFilter implements UIFilter { public String getIdentifier(){return "svframeitem";} public boolean matches(ItemStack stack,String argument,String data,FriendlyFeedbackProvider f){if(stack==null||stack.isEmpty())return false;NBTItem n=new NBTItem(stack);String type=n.getString("SVFRAMEITEMS_ITEM_TYPE");String id=n.getString("SVFRAMEITEMS_ITEM_ID");return (argument==null||argument.isBlank()||argument.equalsIgnoreCase(type))&&(data==null||data.isBlank()||data.equalsIgnoreCase(id));} public boolean isValid(String a,String d,FriendlyFeedbackProvider f){return a!=null&&!a.isBlank();} public boolean fullyDefinesItem(){return false;} public String exampleArgument(){return "SWORD";} public String exampleData(){return "STEEL_SWORD";} }
